\set ON_ERROR_STOP on
begin;
create function pg_temp.assert(v boolean,msg text) returns void language plpgsql as $$begin if not coalesce(v,false) then raise exception 'assertion failed: %',msg;end if;end$$;
select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-8000-000000000001","aal":"aal1"}',false);
select pg_temp.assert((public.game_command('enter_season','{"requestId":"50000000-0000-4000-8000-000000000001","seasonId":"00000000-0000-4000-8000-000000000001"}')->'data'->>'entryId') is not null,'entry created');
create temp table selection as select jsonb_build_object('requestId','50000000-0000-4000-8000-000000000002','roundId','00000000-0000-4000-8000-000000000010','expectedRevision',0,'slots',jsonb_agg(jsonb_build_object('slot',i,'playerId','10000000-0000-4000-8000-'||lpad(i::text,12,'0'))),'captainId','10000000-0000-4000-8000-000000000001','viceCaptainId','10000000-0000-4000-8000-000000000002') input from generate_series(1,18)i;
select pg_temp.assert((public.game_command('confirm_squad',input)->'data'->>'revision')::integer=1,'valid squad') from selection;
select pg_temp.assert((public.game_command('confirm_squad',input)->'data'->>'revision')::integer=1,'idempotent squad') from selection;
select pg_temp.assert(public.game_command('confirm_squad',input||'{"expectedRevision":1}')->'error'->>'code'='IDEMPOTENCY_CONFLICT','changed retry') from selection;
select pg_temp.assert(public.game_command('confirm_squad',input||'{"requestId":"50000000-0000-4000-8000-000000000003"}')->'error'->>'code'='REVISION_CONFLICT','revision conflict') from selection;
select pg_temp.assert(public.game_command('approve_run','{"requestId":"50000000-0000-4000-8000-000000000004"}')->'error'->>'code'='FORBIDDEN','admin MFA');
insert into private.deadline_authorizations(round_id,new_deadline,reason,authorized_by,consumed_at) values('00000000-0000-4000-8000-000000000010',transaction_timestamp(),'synthetic timing test','test',clock_timestamp());
update public.rounds set deadline=transaction_timestamp() where id='00000000-0000-4000-8000-000000000010';
select pg_temp.assert(public.game_command('confirm_squad',input||'{"requestId":"50000000-0000-4000-8000-000000000005","expectedRevision":1}')->'error'->>'code'='ROUND_LOCKED','deadline equality') from selection;
insert into public.scheduled_jobs(id,kind,payload,due_at) values('60000000-0000-4000-8000-000000000001','lock_round','{"roundId":"00000000-0000-4000-8000-000000000010"}',clock_timestamp());
create temp table lease as select (public.worker_claim_jobs('{"workerId":"test","limit":1,"leaseSeconds":60}')->'data'->0) result;
create temp table lease_input as select jsonb_build_object('jobId',result->>'id','leaseToken',result->>'leaseToken','workerId','test') input from lease;
select pg_temp.assert(public.worker_execute_job(input)->'data'->>'executed'='true','lock snapshot') from lease_input;
select pg_temp.assert(exists(select 1 from public.squads where locked_at is not null),'snapshot locked');
update public.scheduled_jobs set lease_expires_at=clock_timestamp()-interval '1 second' where id='60000000-0000-4000-8000-000000000001';
select pg_temp.assert(public.worker_finish_job(input||'{"result":{}}')->'error'->>'code'='LEASE_LOST','expired lease fenced') from lease_input;
select pg_temp.assert(jsonb_array_length(public.worker_claim_jobs('{"workerId":"replacement","limit":1,"leaseSeconds":60}')->'data')=1,'expired lease reclaim');
set local role authenticated;
select pg_temp.assert((select count(*) from public.squads)=1,'owner sees squad');
select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-8000-000000000002","aal":"aal1"}',false);
select pg_temp.assert((select count(*) from public.squads)=0,'unrelated cannot view locked selection');
select pg_temp.assert(not has_table_privilege('authenticated','public.squads','UPDATE'),'direct writes revoked');
select pg_temp.assert(not has_function_privilege('authenticated','public.worker_publish_run(jsonb)','EXECUTE'),'worker grants restricted');
reset role;
rollback;
